pub fn cube_root(n: u8) -> u8 {
    // We cast to u16 to avoid overflow when computing (r+1)^3.
    let un = n as u16;
    let mut r: u8 = 0;
    // Increase r while (r+1)^3 <= n
    while {
        let next = (r + 1) as u16;
        next * next * next <= un
    } {
        r += 1;
    }
    r
}

